import pytest

from pytmc import parser
from pytmc.bin.db import process as db_process
from pytmc.linter import lint_db
from pytmc.pragmas import chains_from_symbol, find_pytmc_symbols
from pytmc.record import (BinaryRecordPackage, EPICSRecord, FloatRecordPackage,
                          IntegerRecordPackage, TwincatTypeRecordPackage,
                          check_record_pv_lengths, get_record_pv_length,
                          missing_epics_macro_substitutions,
                          parse_epics_macro_substitutions, sort_fields)


def test_epics_record_render():
    kwargs = {
        "pvname": "Tst:pv",
        "record_type": "ai",
        "fields": {"ZNAM": "Out", "ONAM": "In"},
        "direction": "input",
    }

    ec = EPICSRecord(**kwargs)
    record = ec.render()
    print(record)  # For debug purposes
    assert kwargs["pvname"] in record
    assert kwargs["record_type"] in record
    for key, value in kwargs["fields"].items():
        assert key in record
        assert value in record


def test_record_pv_length_expands_makefile_macros_and_aliases():
    record = EPICSRecord(
        "$(PREFIX)M1",
        "ai",
        "input",
        aliases=["$(PREFIX)M1:READBACK"],
    )
    macros = parse_epics_macro_substitutions(
        "PREFIX=PLC:TST:,IOCNAME=$(IOC),IOC=$(IOC)"
    )

    assert macros["PREFIX"] == "PLC:TST:"
    assert get_record_pv_length(record, macros) == len("PLC:TST:M1")
    assert get_record_pv_length(
        record, macros, pvname=record.aliases[0]
    ) == len("PLC:TST:M1:READBACK")


def test_record_pv_length_expands_defaults_recursively():
    record = EPICSRecord("$(PREFIX)M1", "ai", "input")

    assert get_record_pv_length(
        record, {"PREFIX": "PLC:$(SITE):", "SITE": "TST"}
    ) == len("PLC:TST:M1")
    assert get_record_pv_length(
        EPICSRecord("$(MISSING=FALLBACK)", "ai", "input"), {}
    ) == len("FALLBACK")


def test_missing_epics_macro_substitutions_checks_nested_values_and_defaults():
    assert missing_epics_macro_substitutions(
        ["$(PREFIX)M1", "$(IOCNAME=DEFAULT)M2"],
        {"PREFIX": "PLC:$(SITE):"},
    ) == {"SITE"}
    assert missing_epics_macro_substitutions(
        ["$(PREFIX)M1", "$(IOCNAME=DEFAULT)M2"],
        {"PREFIX": "PLC:$(SITE):", "SITE": "TST"},
    ) == set()


def test_record_pv_length_reports_unresolved_and_circular_macros():
    record = EPICSRecord("$(PREFIX)M1", "ai", "input")
    with pytest.raises(ValueError, match="No value is available.*PREFIX"):
        get_record_pv_length(record, {})

    circular = EPICSRecord("$(PREFIX)M1", "ai", "input")
    with pytest.raises(ValueError, match="Circular database macro reference"):
        get_record_pv_length(circular, {"PREFIX": "$(PREFIX)"})


def test_record_pv_length_check_reports_overlength_primary_and_alias(caplog):
    record = EPICSRecord(
        "$(PREFIX)M1",
        "ai",
        "input",
        aliases=["$(PREFIX)M1:RBV"],
    )

    check_record_pv_lengths([record], {"PREFIX": "P" * 59})

    assert "PV name" in caplog.text
    assert "alias" in caplog.text
    assert "60 characters" in caplog.text


