def _make_record(direction, record_type="ai", pvname="TST:M1:VAL",
                 autosave=None, fields=None, aliases=None):
    """
    Construct a bare EPICSRecord without needing a full chain.
    """
    if autosave is None:
        autosave = {"pass0": set(), "pass1": set()}
    return EPICSRecord(
        pvname=pvname,
        record_type=record_type,
        direction=direction,
        fields=fields or {},
        autosave=autosave,
        aliases=aliases or [],
    )


def _make_minimal_chain(pvname, alias_setting, io="i"):
    """
    Build a minimal mock chain sufficient to construct a
    TwincatTypeRecordPackage and call generate_input_record.

    The config dict must contain raw unparsed strings for keys that
    normalize_config will parse (io, update, archive) — passing already
    parsed values causes double-parse errors.
    """
    config = {
        "pv": [pvname],
        "io": io,
        "alias": alias_setting,
        "update": "1s poll",
        "archive": "1s scan",
        "field": {},
    }
    chain = MagicMock()
    chain.pvname = pvname
    chain.tcname = "MAIN.motor.fActPosition"
    chain.valid = True
    chain.config = config
    chain.array_info = None

    data_type = MagicMock()
    data_type.is_enum = False
    data_type.is_string = False
    data_type.is_array = False
    data_type.name = "LREAL"
    chain.data_type = data_type
    return chain


def _make_alias_package(pvname, alias_setting):
    """
    Instantiate a TwincatTypeRecordPackage subclass and call
    _configure_aliases directly to test alias resolution in isolation,
    without needing a real chain or ads_port.
    """
    pkg = TwincatTypeRecordPackage.__new__(TwincatTypeRecordPackage)
    pkg.pvname = pvname
    pkg.delimiter = ":"
    pkg.macro_character = "@"
    pkg._configure_aliases(
        pv=pvname,
        macro_character="@",
        alias_setting=alias_setting,
    )
    return pkg


def test_pini_not_in_base_field_defaults():
    """
    PINI must not be present in TwincatTypeRecordPackage.field_defaults.
    All subclasses inherit from this base so verifying it here is sufficient.
    """
    assert "PINI" not in TwincatTypeRecordPackage.field_defaults


def test_pini_not_in_binary_field_defaults():
    """BinaryRecordPackage must not inherit or add PINI."""
    assert "PINI" not in BinaryRecordPackage.field_defaults


def test_pini_not_in_float_field_defaults():
    """FloatRecordPackage must not inherit or add PINI."""
    assert "PINI" not in FloatRecordPackage.field_defaults


def test_pini_not_in_integer_field_defaults():
    """IntegerRecordPackage must not inherit or add PINI."""
    assert "PINI" not in IntegerRecordPackage.field_defaults


def test_input_record_has_no_pini():
    """
    A rendered input record must not contain a PINI field even when all
    field_defaults are applied.
    """
    record = _make_record("input", record_type="ai")
    record.fields.update(TwincatTypeRecordPackage.field_defaults)
    assert "PINI" not in record.render()


def test_update_pini_for_autosave_noop_when_val_in_pass1():
    """
    update_pini_for_autosave must be a no-op even when VAL is in pass1.
    Previously it added PINI=1 in this case.
    """
    record = _make_record(
        "output",
        record_type="ao",
        autosave={"pass0": set(), "pass1": {"VAL"}},
    )
    record.update_pini_for_autosave()
    assert "PINI" not in record.fields


def test_update_pini_for_autosave_noop_when_val_not_in_pass1():
    """update_pini_for_autosave must be a no-op regardless of pass1 contents."""
    record = _make_record(
        "output",
        record_type="ao",
        autosave={"pass0": {"VAL"}, "pass1": set()},
    )
    record.update_pini_for_autosave()
    assert "PINI" not in record.fields


def test_pini_explicit_via_pragma_field_still_works():
    """
    Removing PINI from defaults must not prevent users from adding it
    explicitly via the pragma field key.
    """
    record = _make_record("output", record_type="ao", fields={"PINI": "1"})
    assert "PINI" in record.render()


def test_alias_absolute():
    """An alias with no leading dot must be used exactly as written."""
    pkg = _make_alias_package("TST:M1:fActPosition", "TST:M1.RBV")
    assert pkg.aliases == ["TST:M1.RBV"]


def test_alias_relative_gets_prefix_prepended():
    """
    An alias with a leading dot must have the PV prefix (pvname minus the
    last colon-segment) prepended.
    e.g. pvname=TST:M1:fActPosition, alias=.RBV -> TST:M1.RBV
    """
    pkg = _make_alias_package("TST:M1:fActPosition", ".RBV")
    assert pkg.aliases == ["TST:M1.RBV"]


def test_alias_relative_single_segment_pvname():
    """If the pvname has no colon the full pvname is used as prefix."""
    pkg = _make_alias_package("fActPosition", ".RBV")
    assert pkg.aliases == ["fActPosition.RBV"]


def test_alias_relative_deep_prefix():
    """Prefix derivation works for deeply nested PV names."""
    pkg = _make_alias_package("SYS:SUB:MOT:fPos", ".RBV")
    assert pkg.aliases == ["SYS:SUB:MOT.RBV"]


def test_alias_multiple_mixed_absolute_and_relative():
    """Multiple space-separated aliases with mixed types are all resolved."""
    pkg = _make_alias_package("TST:M1:fActPosition", ".RBV TST:OTHER.DRBV")
    assert pkg.aliases == ["TST:M1.RBV", "TST:OTHER.DRBV"]


def test_alias_macro_character_substituted_in_absolute():
    """The macro character @ must be replaced with $ in absolute aliases."""
    pkg = _make_alias_package("TST:M1:fPos", "@(SYS):M1.RBV")
    assert pkg.aliases == ["$(SYS):M1.RBV"]


def test_alias_macro_character_substituted_in_relative():
    """The macro character @ must be replaced with $ in relative aliases."""
    pkg = _make_alias_package("$(PREFIX)MOTOR:fPos", ".RBV")
    assert pkg.aliases == ["$(PREFIX)MOTOR.RBV"]


def test_alias_empty_setting_produces_no_aliases():
    """An empty alias_setting must result in an empty aliases list."""
    pkg = _make_alias_package("TST:M1:fPos", "")
    assert pkg.aliases == []


def test_alias_whitespace_only_produces_no_aliases():
    """A whitespace-only alias_setting must result in an empty aliases list."""
    pkg = _make_alias_package("TST:M1:fPos", "   ")
    assert pkg.aliases == []


def test_alias_rendered_in_record_block():
    """Aliases must appear as alias("...") lines in the rendered record."""
    record = _make_record(
        "input",
        record_type="ai",
        pvname="TST:M1:fActPosition_RBV",
        aliases=["TST:M1.RBV"],
    )
    assert 'alias("TST:M1.RBV")' in record.render()


def test_alias_multiple_all_rendered():
    """All aliases must appear in the rendered record block."""
    record = _make_record(
        "input",
        record_type="ai",
        pvname="TST:M1:fActPosition_RBV",
        aliases=["TST:M1.RBV", "TST:OTHER.DRBV"],
    )
    rendered = record.render()
    assert 'alias("TST:M1.RBV")' in rendered
    assert 'alias("TST:OTHER.DRBV")' in rendered


def test_generate_input_record_pvname_gets_rbv_suffix():
    """The input record PV name must have _RBV appended."""
    chain = _make_minimal_chain("TST:M1:fActPosition", ".RBV")
    pkg = FloatRecordPackage(ads_port=851, chain=chain)
    record = pkg.generate_input_record()
    assert record.pvname == "TST:M1:fActPosition_RBV"


def test_generate_input_record_absolute_alias_not_modified_by_add_rbv():
    """
    An absolute alias must not have _RBV appended by the add_rbv helper
    inside generate_input_record.
    """
    chain = _make_minimal_chain("TST:M1:fActPosition", "TST:M1.RBV")
    pkg = FloatRecordPackage(ads_port=851, chain=chain)
    record = pkg.generate_input_record()
    assert "TST:M1.RBV" in record.aliases
    assert "TST:M1.RBV_RBV" not in record.aliases


def test_generate_input_record_relative_alias_not_modified_by_add_rbv():
    """
    A relative alias resolved to its full form must not have _RBV appended
    by add_rbv in generate_input_record.
    """
    chain = _make_minimal_chain("TST:M1:fActPosition", ".RBV")
    pkg = FloatRecordPackage(ads_port=851, chain=chain)
    record = pkg.generate_input_record()
    assert "TST:M1.RBV" in record.aliases
    assert "TST:M1.RBV_RBV" not in record.aliases


def test_io_io_alias_only_on_output_record_not_input():
    """
    For io:io variables both an input (_RBV) and output record are generated.
    The alias must only appear on the output record — putting it on both
    causes EPICS to fail on boot with 'dbCreateAlias: Add to PVD failed'
    because the same alias name cannot be registered twice in the PVD.
    """
    chain = _make_minimal_chain("TST:M1:bHalt", ".STOP", io="io")
    pkg = BinaryRecordPackage(ads_port=851, chain=chain)
    input_record = pkg.generate_input_record()
    output_record = pkg.generate_output_record()

    assert "TST:M1.STOP" in output_record.aliases, (
        "Alias must be present on the output record"
    )
    assert input_record.aliases == [], (
        "Alias must not be on the input record for io:io — "
        "would cause dbCreateAlias duplicate error on IOC boot"
    )


def _epics_records_from_tmc(tmc_path):
    """
    Parse a tmc file and return all EPICSRecord objects.

    db_process returns RecordPackage objects. We expand each valid package
    into its individual EPICSRecord instances so tests can inspect direction,
    fields, and rendered output directly.
    Errors are allowed so a partial tmc still produces usable records.
    """
    tmc = parser.parse(tmc_path)
    packages, _ = db_process(
        tmc, dbd_file=None, allow_errors=True, show_error_context=True
    )
    return [
        epics_record
        for pkg in packages
        if pkg.valid
        for epics_record in pkg.records
    ]


def test_no_pini_in_any_input_record_from_tmc(tmc_filename):
    """
    No input record generated from any tmc file in the test suite must
    contain a PINI field. PINI was previously injected via field_defaults
    and is now removed — autosave handles value restore on IOC restart.
    """
    epics_records = _epics_records_from_tmc(tmc_filename)
    bad = [r for r in epics_records if r.direction == "input" and "PINI" in r.render()]
    assert bad == [], (
        f"Input records with unexpected PINI in {tmc_filename.name}:\n"
        + "\n".join(f"  {r.pvname}" for r in bad)
    )


def test_no_pini_on_output_record_from_tmc(tmc_filename):
    """
    No output record must have PINI added automatically, even when VAL is
    in autosave pass1. update_pini_for_autosave must be a no-op.
    """
    epics_records = _epics_records_from_tmc(tmc_filename)
    bad = [r for r in epics_records if r.direction == "output" and "PINI" in r.render()]
    assert bad == [], (
        f"Output records with unexpected PINI in {tmc_filename.name}:\n"
        + "\n".join(f"  {r.pvname}" for r in bad)
    )


def test_alias_pragma_produces_alias_in_record_from_tmc(tmc_filename):
    """
    For every chain that has an alias: pragma, the generated record must
    contain a corresponding alias("...") line.
    Skipped when no alias pragmas are present in the tmc.
    """
    tmc = parser.parse(tmc_filename)
    chains_with_alias = [
        chain
        for sym in find_pytmc_symbols(tmc)
        for chain in chains_from_symbol(sym)
        if chain.config.get("alias")
    ]
    if not chains_with_alias:
        pytest.skip(f"No alias pragmas in {tmc_filename.name}")

    packages, _ = db_process(tmc, dbd_file=None, allow_errors=True, show_error_context=True)
    epics_records = [r for pkg in packages if pkg.valid for r in pkg.records]
    by_base_pv = {r.pvname.replace("_RBV", ""): r for r in epics_records}

    for chain in chains_with_alias:
        record = by_base_pv.get(chain.pvname)
        assert record is not None, f"No record for chain pv {chain.pvname}"
        assert "alias(" in record.render(), (
            f"Record {record.pvname} has alias pragma but no alias() in output"
        )


def test_alias_not_mangled_with_rbv_suffix_from_tmc(tmc_filename):
    """
    Aliases must not have _RBV appended by the add_rbv helper inside
    generate_input_record. Skipped when no alias pragmas are present.

    We check only alias("...") lines, not the full rendered record —
    input record PV names legitimately end with _RBV and must not be
    confused with a mangled alias.
    """
    tmc = parser.parse(tmc_filename)
    has_alias = any(
        chain.config.get("alias")
        for sym in find_pytmc_symbols(tmc)
        for chain in chains_from_symbol(sym)
    )
    if not has_alias:
        pytest.skip(f"No alias pragmas in {tmc_filename.name}")

    packages, _ = db_process(tmc, dbd_file=None, allow_errors=True, show_error_context=True)
    epics_records = [r for pkg in packages if pkg.valid for r in pkg.records]
    for r in epics_records:
        for alias_line in re.findall(r'alias\("([^"]+)"\)', r.render()):
            assert not alias_line.endswith("_RBV"), (
                f"Record {r.pvname} has alias with _RBV suffix ({alias_line!r}) — "
                "alias was incorrectly mangled by add_rbv"
            )
